routerAdd('GET','/api/pfriends/admin/gamification/rules',(e)=>{const rules=require(`${__hooks}/gamification-rules-utils.js`);rules.requireAdmin(e);const data=rules.response(e.app);data.audits=rules.audits(e.app,20);return e.json(200,data);},$apis.requireAuth('users'));

routerAdd('POST','/api/pfriends/admin/gamification/tiers/preview',(e)=>{const rules=require(`${__hooks}/gamification-rules-utils.js`);rules.requireAdmin(e);const body=e.requestInfo().body||{},current=require(`${__hooks}/gamification-utils.js`).tiers(e.app),thresholds=rules.normalize(body.thresholds,current);return e.json(200,rules.response(e.app,thresholds));},$apis.requireAuth('users'));

routerAdd('PUT','/api/pfriends/admin/gamification/tiers',(e)=>{const rules=require(`${__hooks}/gamification-rules-utils.js`);rules.requireAdmin(e);const body=e.requestInfo().body||{},current=require(`${__hooks}/gamification-utils.js`).tiers(e.app),thresholds=rules.normalize(body.thresholds,current),version=rules.versionOf(current);if(String(body.expectedVersion||'')!==version)throw new BadRequestError('Konfigurasi tier sudah berubah. Muat ulang dan tinjau dampaknya kembali.');const preview=rules.impact(e.app,current,thresholds),before=Object.fromEntries(current.map(t=>[t.level,t.threshold])),now=new Date().toISOString();e.app.runInTransaction((tx)=>{for(const tier of current){const row=tx.findRecordById('gamification_tiers',tier.id);row.set('threshold',thresholds[tier.level]);row.set('updatedBy',e.auth.id);row.set('updatedAt',now);tx.save(row);}const audit=new Record(tx.findCollectionByNameOrId('gamification_tier_audits'));audit.set('actor',e.auth.id);audit.set('actorName',e.auth.getString('displayName'));audit.set('before',before);audit.set('after',thresholds);audit.set('impact',preview);audit.set('occurredAt',now);tx.save(audit);const gamification=require(`${__hooks}/gamification-utils.js`),rewards=require(`${__hooks}/reward-utils.js`);for(const profile of tx.findRecordsByFilter('gamification_profiles','id != ""','fullName',0,0)){const awardee=tx.findRecordById('awardees',profile.getString('awardee'));gamification.ensureProfile(tx,awardee,profile.getInt('totalPoints'));rewards.syncWallet(tx,awardee);}});const result=rules.response(e.app);result.audits=rules.audits(e.app,20);return e.json(200,result);},$apis.requireAuth('users'));

routerAdd('GET','/api/pfriends/admin/gamification/tiers/audit',(e)=>{const rules=require(`${__hooks}/gamification-rules-utils.js`);rules.requireAdmin(e);return e.json(200,{audits:rules.audits(e.app,100)});},$apis.requireAuth('users'));
